import { test, expect, Page } from '@playwright/test';

test.describe('Rate Limit Error Handling', () => {
  let page: Page;
  const baseUrl = 'http://localhost:3000';
  const formSubmitButton = 'Submit';
  const emailInput = 'email';
  const messageInput = 'message';

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto(baseUrl);
  });

  test('should display rate limit error after exceeding submission threshold', async () => {
    // Fill form with valid data
    await page.getByLabel(emailInput).fill('test@example.com');
    await page.getByLabel(messageInput).fill('Test message');

    // Submit form multiple times to trigger rate limit
    const submissionLimit = 5;
    for (let i = 0; i < submissionLimit; i++) {
      await page.getByRole('button', { name: formSubmitButton }).click();
      await page.waitForTimeout(100);
    }

    // Verify rate limit error message is displayed
    const errorMessage = page.getByText(/rate limit|too many requests|please try again later/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should show specific rate limit error with retry information', async () => {
    // Fill and submit form rapidly
    await page.getByLabel(emailInput).fill('user@test.com');
    await page.getByLabel(messageInput).fill('Rapid submission test');

    // Perform rapid submissions
    for (let i = 0; i < 6; i++) {
      await page.getByRole('button', { name: formSubmitButton }).click();
      await page.waitForTimeout(50);
    }

    // Check for rate limit error with retry information
    const rateLimitError = page.getByRole('alert');
    await expect(rateLimitError).toBeVisible();

    const errorText = await rateLimitError.textContent();
    expect(errorText).toMatch(/rate limit|too many|retry|wait/i);
  });

  test('should disable submit button during rate limit period', async () => {
    // Fill form
    await page.getByLabel(emailInput).fill('blocked@example.com');
    await page.getByLabel(messageInput).fill('Testing button disable');

    // Submit form multiple times
    const submitButton = page.getByRole('button', { name: formSubmitButton });
    for (let i = 0; i < 5; i++) {
      await submitButton.click();
      await page.waitForTimeout(100);
    }

    // Verify button is disabled after rate limit
    await expect(submitButton).toBeDisabled();
  });

  test('should recover from rate limit after waiting', async () => {
    // Fill form
    await page.getByLabel(emailInput).fill('recovery@test.com');
    await page.getByLabel(messageInput).fill('Recovery test');

    // Trigger rate limit
    const submitButton = page.getByRole('button', { name: formSubmitButton });
    for (let i = 0; i < 5; i++) {
      await submitButton.click();
      await page.waitForTimeout(100);
    }

    // Verify rate limit error appears
    await expect(page.getByText(/rate limit|too many requests/i)).toBeVisible();

    // Wait for rate limit to reset (simulated with shorter timeout for testing)
    await page.waitForTimeout(2000);

    // Verify button is re-enabled
    await expect(submitButton).toBeEnabled();

    // Attempt new submission
    await page.getByLabel(emailInput).fill('recovery2@test.com');
    await submitButton.click();

    // Verify no rate limit error on new submission
    const rateLimitError = page.getByText(/rate limit|too many requests/i);
    await expect(rateLimitError).not.toBeVisible();
  });

  test('should show countdown timer in rate limit error message', async () => {
    // Fill form
    await page.getByLabel(emailInput).fill('timer@test.com');
    await page.getByLabel(messageInput).fill('Timer test');

    // Trigger rate limit
    const submitButton = page.getByRole('button', { name: formSubmitButton });
    for (let i = 0; i < 5; i++) {
      await submitButton.click();
      await page.waitForTimeout(100);
    }

    // Look for countdown timer in error message
    const errorAlert = page.getByRole('alert');
    await expect(errorAlert).toBeVisible();

    const timerText = await errorAlert.textContent();
    // Check if timer or seconds information is present
    expect(timerText).toMatch(/\d+\s*(?:second|sec|s)|retry|wait/i);
  });
});
